import com.skillforge.platform.dto.ApiResponse;
import com.skillforge.platform.dto.CreateSkillRequest;
import com.skillforge.platform.dto.UpdateSkillRequest;
import com.skillforge.platform.entity.Skill;
import com.skillforge.platform.entity.User;
import com.skillforge.platform.service.SkillService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/skills")
public class SkillController {

    private final SkillService skillService;

    public SkillController(SkillService skillService) {
        this.skillService = skillService;
    }

    @GetMapping
    public ApiResponse<List<Skill>> list() {
        return ApiResponse.success(skillService.listSkills(currentUser()));
    }

    @PostMapping
    public ApiResponse<Skill> create(@RequestBody CreateSkillRequest request) throws IOException {
        if (skillService.findByName(request.getName()) != null) {
            return ApiResponse.error(400, "技能名称已存在");
        }
        Skill skill = skillService.createSkill(request, currentUser());
        return ApiResponse.success("创建成功", skill);
    }

    @GetMapping("/{id}")
    public ApiResponse<Map<String, Object>> detail(@PathVariable Long id) {
        Skill skill = skillService.findById(id);
        if (skill == null) {
            return ApiResponse.error(404, "技能不存在");
        }
        return ApiResponse.success(skillService.getSkillDetail(skill));
    }

    @PutMapping("/{id}")
    public ApiResponse<Skill> update(@PathVariable Long id, @RequestBody UpdateSkillRequest request) {
        Skill skill = skillService.findById(id);
        if (skill == null) {
            return ApiResponse.error(404, "技能不存在");
        }
        if (!skillService.canOperate(skill, currentUser())) {
            return ApiResponse.error(403, "无权操作");
        }
        Skill updated = skillService.updateSkill(skill, request);
        return ApiResponse.success("更新成功", updated);
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable Long id) throws IOException {
        Skill skill = skillService.findById(id);
        if (skill == null) {
            return ApiResponse.error(404, "技能不存在");
        }
        if (!skillService.canOperate(skill, currentUser())) {
            return ApiResponse.error(403, "无权操作");
        }
        skillService.deleteSkill(skill);
        return ApiResponse.success("删除成功", null);
    }

    private User currentUser() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        return (User) authentication.getPrincipal();
    }
}
